import { Component } from "../components/Component.js";
import { IMAGE_PREVIEW } from "../config/component.config.js";
import type { ImagePreviewOptions } from "../types/component.types.js";
import type {
  ElementTranslatePosition,
  ImagePreviewBinding,
} from "../types/runtime.types.js";
import { Helpers } from "../utils/Helpers.js";
import { ResponsiveRuntime } from "../runtime/ResponsiveRuntime.js";

export class ImagePreview extends Component {
  private readonly list: HTMLElement;
  private readonly preview: HTMLElement;
  private readonly previewImg: HTMLImageElement;
  private readonly itemSelector: string;
  private readonly imageDataAttr: string;
  private readonly offset: number;
  private readonly onMove: (event: MouseEvent) => void;
  private readonly bindings: ImagePreviewBinding[] = [];
  private hideTimer: number | null = null;
  private switchTimer: number | null = null;
  private currentItem: HTMLElement | null = null;

  constructor(
    list: HTMLElement,
    preview: HTMLElement,
    previewImg: HTMLImageElement,
    itemSelector: string,
    imageDataAttr: string,
    offset: number,
  ) {
    super();
    this.list = list;
    this.preview = preview;
    this.previewImg = previewImg;
    this.itemSelector = itemSelector;
    this.imageDataAttr = imageDataAttr;
    this.offset = offset;
    this.onMove = Helpers.throttle((...args: unknown[]) => {
      const event = args[0];
      if (!(event instanceof MouseEvent)) return;
      this._move(event.clientX, event.clientY);
    }, IMAGE_PREVIEW.moveThrottleMs) as (event: MouseEvent) => void;
  }

  static init(options: ImagePreviewOptions = {}): void {
    const responsive = ResponsiveRuntime.getDefault().getSnapshot();
    if (!responsive.flags.hoverCapable) {
      return;
    }

    const listSelector = options.listSelector ?? IMAGE_PREVIEW.listSelector;
    const itemSelector = options.itemSelector ?? IMAGE_PREVIEW.itemSelector;
    const previewSelector =
      options.previewSelector ?? IMAGE_PREVIEW.previewSelector;
    const imageDataAttr =
      options.imageDataAttr ?? IMAGE_PREVIEW.imageDataAttr;
    const offset = options.offset ?? IMAGE_PREVIEW.offset;

    const list = document.querySelector<HTMLElement>(listSelector);
    const preview = document.querySelector<HTMLElement>(previewSelector);
    const previewImg = preview?.querySelector<HTMLImageElement>("img");
    if (!list || !preview || !previewImg) return;

    const imagePreview = new ImagePreview(
      list,
      preview,
      previewImg,
      itemSelector,
      imageDataAttr,
      offset,
    );
    imagePreview.init();
  }

  protected mount(): void {
    const items = Array.from(
      this.list.querySelectorAll<HTMLElement>(this.itemSelector),
    );
    if (items.length === 0) return;
    items.forEach((item) => this._bindItem(item));
  }

  protected applyVisibility(visible: boolean): void {
    this.preview.classList.toggle(IMAGE_PREVIEW.visibleClass, visible);
  }

  getVisibleState(): boolean {
    return this.preview.classList.contains(IMAGE_PREVIEW.visibleClass);
  }

  override dispose(): void {
    this._clearHideTimer();
    this._clearSwitchTimer();
    this.bindings.forEach((binding) => {
      binding.item.removeEventListener("mouseenter", binding.onEnter);
      binding.item.removeEventListener("mousemove", binding.onMove);
      binding.item.removeEventListener("mouseleave", binding.onLeave);
      delete binding.item.dataset[IMAGE_PREVIEW.boundFlag];
    });
    this.bindings.length = 0;
    super.dispose();
  }

  private _bindItem(item: HTMLElement): void {
    if (item.dataset[IMAGE_PREVIEW.boundFlag] === "true") return;
    const binding: ImagePreviewBinding = {
      item,
      onEnter: (event) => this._onEnter(item, event),
      onMove: this.onMove,
      onLeave: () => this._scheduleHide(),
    };
    item.dataset[IMAGE_PREVIEW.boundFlag] = "true";
    item.addEventListener("mouseenter", binding.onEnter);
    item.addEventListener("mousemove", binding.onMove);
    item.addEventListener("mouseleave", binding.onLeave);
    this.bindings.push(binding);
  }

  private _onEnter(item: HTMLElement, event: MouseEvent): void {
    this._clearHideTimer();
    this._clearSwitchTimer();
    this.preview.classList.remove(IMAGE_PREVIEW.closingClass);

    const imageSrc = item.getAttribute(this.imageDataAttr);
    if (!imageSrc) return;

    if (this._shouldSwitchImage(item)) {
      this._startClosing();
      this.switchTimer = window.setTimeout(() => {
        this.previewImg.src = imageSrc;
        this.preview.classList.remove(IMAGE_PREVIEW.closingClass);
        this._show();
        this.switchTimer = null;
      }, IMAGE_PREVIEW.switchDelayMs);
    } else {
      this.previewImg.src = imageSrc;
      this._show();
    }

    this.currentItem = item;
    this._move(event.clientX, event.clientY);
  }

  private _shouldSwitchImage(item: HTMLElement): boolean {
    return (
      this.preview.classList.contains(IMAGE_PREVIEW.visibleClass) &&
      this.currentItem !== null &&
      this.currentItem !== item
    );
  }

  private _move(clientX: number, clientY: number): void {
    const responsive = ResponsiveRuntime.getDefault().getSnapshot();
    const width = this.preview.getBoundingClientRect().width || 320;
    const height = this.preview.getBoundingClientRect().height || 220;
    const left = this._resolveAxisPosition(
      clientX,
      width,
      responsive.viewportWidth,
    );
    const top = this._resolveAxisPosition(
      clientY,
      height,
      responsive.viewportHeight,
    );
    this._applyPreviewPosition({ x: left, y: top });
  }

  private _resolveAxisPosition(
    clientPosition: number,
    boxSize: number,
    viewportSize: number,
  ): number {
    const offsetPosition = clientPosition + this.offset;
    const exceedsViewport = offsetPosition + boxSize > viewportSize - this.offset;
    const fallbackPosition = clientPosition - boxSize - this.offset;
    const nextPosition = exceedsViewport ? fallbackPosition : offsetPosition;
    return Math.max(this.offset, nextPosition);
  }

  private _applyPreviewPosition(position: ElementTranslatePosition): void {
    this.preview.style.left = `${position.x}px`;
    this.preview.style.top = `${position.y}px`;
  }

  private _scheduleHide(): void {
    this._clearHideTimer();
    this._clearSwitchTimer();
    this.hideTimer = window.setTimeout(() => {
      this._startClosing();
      window.setTimeout(() => {
        this.preview.classList.remove(IMAGE_PREVIEW.closingClass);
      }, IMAGE_PREVIEW.closeAnimationMs);
      this.currentItem = null;
      this.hideTimer = null;
    }, 80);
  }

  private _startClosing(): void {
    this._hide();
    this.preview.classList.add(IMAGE_PREVIEW.closingClass);
  }

  private _show(): void {
    this.setVisibleOn();
  }

  private _hide(): void {
    this.setVisibleOff();
  }

  private _clearHideTimer(): void {
    if (this.hideTimer === null) return;
    window.clearTimeout(this.hideTimer);
    this.hideTimer = null;
  }

  private _clearSwitchTimer(): void {
    if (this.switchTimer === null) return;
    window.clearTimeout(this.switchTimer);
    this.switchTimer = null;
  }
}

