189	function syncWhyScene(progress: number): void {
190	  const body = document.querySelector<HTMLElement>(WHY_BODY_SELECTOR);
191	  const visual = document.querySelector<HTMLElement>(WHY_VISUAL_SELECTOR);
192	  const textItems = Array.from(
193	    document.querySelectorAll<HTMLElement>(WHY_TEXT_SELECTOR),
194	  );
195	  if (!body || !visual) return;
196	
197	  const bodyRevealProgress = remapWhyProgress(
198	    progress,
199	    WHY_REVEAL_START,
200	    WHY_REVEAL_END,
201	  );
202	  const visualRevealProgress = easeOutWhyProgress(bodyRevealProgress);
203	
204	  body.style.opacity = String(bodyRevealProgress);
205	  body.style.visibility = bodyRevealProgress > 0 ? "visible" : "hidden";
206	  body.style.transform = `translate3d(-50%, calc(-50% + ${Helpers.lerp(48, 0, bodyRevealProgress)}px), 0)`;
207	
