function syncWhyScene(progress: number): void {
  const body = document.querySelector<HTMLElement>(WHY_BODY_SELECTOR);
  const visual = document.querySelector<HTMLElement>(WHY_VISUAL_SELECTOR);
  const textItems = Array.from(
    document.querySelectorAll<HTMLElement>(WHY_TEXT_SELECTOR),
  );
  if (!body || !visual) return;

  const bodyRevealProgress = remapWhyProgress(
    progress,
    WHY_REVEAL_START,
    WHY_REVEAL_END,
  );
  const visualRevealProgress = easeOutWhyProgress(bodyRevealProgress);

  body.style.opacity = String(bodyRevealProgress);
  body.style.visibility = bodyRevealProgress > 0 ? "visible" : "hidden";
  body.style.transform = `translate3d(-50%, calc(-50% + ${Helpers.lerp(48, 0, bodyRevealProgress)}px), 0)`;

  visual.style.opacity = String(visualRevealProgress);
  visual.style.visibility = visualRevealProgress > 0 ? "visible" : "hidden";
  visual.style.transform = "translate3d(-50%, -50%, 0)";

  const shouldShowText =
    progress >= WHY_REVEAL_START && progress < WHY_HIDE_START;
  if (mainSceneDomState.isWhyTextVisible === shouldShowText) return;
  mainSceneDomState.isWhyTextVisible = shouldShowText;
  mainSceneDomState.whyTextTimers = clearTimers(
    mainSceneDomState.whyTextTimers,
  );
  if (textItems.length === 0) return;

  const items = shouldShowText ? textItems : textItems.slice().reverse();
  items.forEach((item, index) => {
    const timerId = window.setTimeout(
      () => {
        if (shouldShowText) {
          TextReveal.setVisibleOn(item);
          return;
        }
        TextReveal.setVisibleOff(item);
      },
      index * WHY_TEXT_STAGGER_SECONDS * 1000,
    );
    mainSceneDomState.whyTextTimers.push(timerId);
  });
}

function disposeWhyScene(): void {
  mainSceneDomState.isWhyTextVisible = false;
  mainSceneDomState.whyTextTimers = clearTimers(
    mainSceneDomState.whyTextTimers,
  );
  const body = document.querySelector<HTMLElement>(WHY_BODY_SELECTOR);
  const visual = document.querySelector<HTMLElement>(WHY_VISUAL_SELECTOR);
  const textItems = Array.from(
    document.querySelectorAll<HTMLElement>(WHY_TEXT_SELECTOR),
  );

  textItems.forEach((item) => TextReveal.setVisibleOff(item));
  if (body) {
    body.style.opacity = "0";
    body.style.visibility = "hidden";
    body.style.transform = "translate3d(-50%, calc(-50% + 48px), 0)";
  }
  if (visual) {
    visual.style.opacity = "0";
    visual.style.visibility = "hidden";
    visual.style.transform = "translate3d(-50%, -50%, 0)";
  }
}

