class PageGlobalUiRuntime {
  private _headerUi: Header | null = null;
  private _workModalUi: WorkModal | null = null;
  private readonly _dropdownUis = new Set<Dropdown>();
  private readonly _pinnedRevealRuntime = new PinnedRevealRuntime();
  private readonly _qaManager = new QaManager();

  init(root?: ParentNode | null): void {
    this._initUiToggles(root);
    Drawer.getInstance({
      revealGroups: DOM_CONFIG.drawer.revealGroups,
    }).init();
    CustomCursor.init({ root });
    MagneticCornerTracker.init({ root });
    updateStaticCornerSizes(root);
    TextReveal.init({
      root,
      excludeSelectors: DOM_CONFIG.maskingExcludeSelectors ?? [],
    });
    BlockReveal.init({ root });
    ShareButton.init({ root });
    ContactFormValidation.init({ root });
    ContactWizard.init({ root });
    this._qaManager.init({ root });
    Suspense.init({ root });
    Category.init(undefined, root ?? document);
    Marquee.init({ root });
    if (
      typeof document !== "undefined" &&
      document.querySelector("[data-award-hover-preview]") !== null
    ) {
      ImagePreview.init();
    }
    this._pinnedRevealRuntime.init(PINNED_REVEALS);
  }

  syncAfterContainerChange(): void {
    Drawer.syncNavActiveState();
    updateStaticCornerSizes();
  }

  dispose(): void {
    this._disposeUiToggles();
    MagneticCornerTracker.destroyAll();
    CustomCursor.dispose();
    TextReveal.dispose();
    BlockReveal.dispose();
    Marquee.dispose();
    this._pinnedRevealRuntime.dispose();
    this._qaManager.dispose();
  }

  private _initUiToggles(root?: ParentNode | null): void {
    this._headerUi?.dispose();
    this._headerUi = new Header();
    this._headerUi.init();

    this._workModalUi?.dispose();
    this._workModalUi = new WorkModal({ root });
    this._workModalUi.init();

    this._dropdownUis.forEach((dropdown) => dropdown.dispose());
    this._dropdownUis.clear();
    const scope = root ?? document;
    const roots = scope.querySelectorAll<HTMLElement>("[data-dropdown]");
    roots.forEach((root) => {
      const dropdown = new Dropdown(root, { openClass: "is-open" });
      dropdown.init();
      this._dropdownUis.add(dropdown);
    });
  }

  private _disposeUiToggles(): void {
    this._headerUi?.dispose();
    this._headerUi = null;
    this._workModalUi?.dispose();
    this._workModalUi = null;
    this._dropdownUis.forEach((dropdown) => dropdown.dispose());
    this._dropdownUis.clear();
    CloseAllExpanded.offCloseAllImmediate();

