    margin-top: fluid(4, 10);
  }

  &__title-part {
    display: inline-block;
  }

  &__title-part--ghost {
    opacity: 0;
  }

  &__card-list {
    position: absolute;
    inset: 0;
    margin: 0;
    padding: 0;
    list-style: none;
    pointer-events: none;
  }

  &__card {
    --about-who-card-x: 0vmin;
    --about-who-card-y: 0vmin;
    --about-who-card-rotate: 0deg;
    --about-who-card-scale: 0.88;
    --about-who-card-opacity: 0;
    --about-who-card-z: 1;

    position: absolute;
    display: flex;
    left: 50%;
    top: 50%;
    width: min(26vmin, 280px);
    flex-direction: column;
    gap: fluid(10, 14);
    transform: translate3d(
        calc(-50% + var(--about-who-card-x)),
        calc(-50% + var(--about-who-card-y)),
        0
      )
      rotate(var(--about-who-card-rotate)) scale(var(--about-who-card-scale));
    transform-origin: center;
    opacity: var(--about-who-card-opacity);
    z-index: var(--about-who-card-z);
    will-change: transform, opacity;
  }

  &__card-media {
    position: relative;
    width: 100%;
    margin: 0;
    overflow: hidden;
    border: 1px solid
      color-mix(in srgb, var(--clr-white-100) 14%, transparent);
    background: color-mix(in srgb, var(--clr-black-100) 72%, transparent);
    box-shadow:
      0 20px 40px rgba(0, 0, 0, 0.32),
      0 0 0 1px rgba(255, 255, 255, 0.06);
  }

  &__card-image {
    display: block;
    width: 100%;
    aspect-ratio: 4 / 5;
    object-fit: cover;
  }

  @include mq(md) {
    &__wrap {
      min-height: var(--scene-shell-span);
    }

    &__body {
      max-width: none;
    }

    &__inner {
      position: relative;
      top: auto;
      height: auto;
      min-height: 100vh;
    }

    &__visual {
      min-height: 100vh;
    }

    &__showcase {
      width: min(100vw - 2rem, 32rem);
      height: min(70vh, 32rem);
    }

    &__title-line {
      gap: fluid(12, 18);
    }

    &__card {
      width: min(32vmin, 232px);
    }

    &__ring {
      width: min(66vmin, 420px);
    }
  }
