import type { IUIComponent } from "../types/engine.types.js";

export abstract class Component implements IUIComponent {
  protected _disposed = false;

  init(): void {
    if (this._disposed) return;
    this.mount();
  }

  protected abstract mount(): void;
  protected abstract applyVisibility(visible: boolean): void;
  abstract getVisibleState(): boolean;

  setVisibleOn(): void {
    this.applyVisibility(true);
  }

  setVisibleOff(): void {
    this.applyVisibility(false);
  }

  dispose(): void {
    this._disposed = true;
  }
}

