&-why {
  width: 100%;

  &__wrap {
    min-height: var(--scene-shell-span);
    position: relative;

    > .no-container-2xl {
      min-height: inherit;
    }
  }

  &__inner {
    width: 100%;
    display: flex;
    align-items: center;
    opacity: 0;
    visibility: hidden;
    transition:
      opacity var(--transition-default),
      visibility var(--transition-default);
    will-change: opacity;

    &.is-visible {
      opacity: 1;
      visibility: visible;
    }
  }

  // ── 스킬 리스트 ────────────────────────────────
  &__skill-list {
    width: 100%;
  }

  &__skill-item {
    display: flex;
    align-items: baseline;
    gap: var(--gutter-lg);
    padding: fluid(14, 24) 0;
    border-bottom: 1px solid color-mix(in srgb, currentColor 16%, transparent);
    cursor: default;
    transition: opacity var(--transition-base);

    &:first-child {
      border-top: 1px solid color-mix(in srgb, currentColor 16%, transparent);
    }
  }

  &__skill-list:has(&__skill-item:hover) &__skill-item:not(:hover) {
    opacity: 0.24;
  }

  &__skill-num {
    min-width: fluid(24, 36);
    opacity: 0.4;
  }

  &__skill-label {
    flex: 1;
    line-height: 1;
  }

  &__skill-tag {
    opacity: 0.4;
    text-transform: uppercase;
    letter-spacing: 0.08em;
  }

  // ── 비디오 프리뷰 ──────────────────────────────
  &__preview {
    position: fixed;
    top: 50%;
    left: fluid(24, 56);
    transform: translateY(-50%) scale(0.9);
    width: fluid(160, 240);
    aspect-ratio: 9 / 16;
    border-radius: var(--radius-md, 12px);
    overflow: hidden;
    opacity: 0;
    visibility: hidden;
    pointer-events: none;
    transition:
      opacity 0.32s ease,
      visibility 0.32s ease,
      transform 0.32s ease;
    z-index: 100;

    &.is-visible {
      opacity: 1;
      visibility: visible;

