function remapWhyProgress(value: number, start: number, end: number): number {
  if (value <= start) return 0;
  if (value >= end) return 1;
  return (value - start) / Math.max(end - start, Number.EPSILON);
}

function easeOutWhyProgress(value: number): number {
  const clampedValue = Helpers.clamp01(value);
  return 1 - Math.pow(1 - clampedValue, 3);
}

